def cmd_dict(t1=None, t2=None, t3=None, arch=None):
    d = {}
    if t1 is not None: d['tier1'] = t1
    if t2 is not None: d['tier2'] = t2
    if t3 is not None: d['tier3'] = t3
    if arch is not None: d['arch'] = arch
    return d

def body(*lines):
    return '\n'.join(lines)

